"""Plain text absence notices for parents."""

from rosterkit.models import Student
from rosterkit.errors import ProjectError

class NoticeError(ProjectError):
    """A notice cannot be written from the given marks."""

def _verify(student: Student, marks: list) -> None:
    for mark in marks:
        if mark.student_id != student.student_id:
            raise NoticeError(
                f"mark for {mark.student_id} given"
                f" to {student.student_id}"
            )

def absent_dates(student: Student, marks: list) -> list:
    """Sorted distinct days marked absent."""
    _verify(student, marks)
    days = {
        mark.day for mark in marks
        if mark.status == "absent"
    }
    return sorted(days)

def _compose(student: Student, days: list) -> str:
    word = "day" if len(days) == 1 else "days"
    name = f"{student.first_name} {student.last_name}"
    when = ", ".join(stamp.isoformat() for stamp in days)
    head = f"{name} missed {len(days)} {word}."
    return f"{head}\nDates: {when}"

def build_notice(student: Student, marks: list) -> str:
    """Short notice with the student and absent dates."""
    days = absent_dates(student, list(marks))
    if not days:
        raise NoticeError("no absences to report")
    return _compose(student, days)
